# Validate inputs
if not all(isinstance(arr, np.ndarray) for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("All inputs must be numpy arrays.")
if any(arr.ndim != 2 for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("All input arrays must be 2-dimensional.")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All input arrays must have the same shape.")
if any(arr.size == 0 for arr in [logp_with_result, logp_call_only, logp_no_call]):
    raise ValueError("Input arrays must not be empty.")
if not (np.all(np.isfinite(logp_with_result)) and np.all(np.isfinite(logp_call_only)) and np.all(np.isfinite(logp_no_call))):
    raise ValueError("All values in input arrays must be finite.")
if not (np.all(logp_with_result <= 0) and np.all(logp_call_only <= 0) and np.all(logp_no_call <= 0)):
    raise ValueError("All values in input arrays must be nonpositive.")
# Validate tau_filter
if isinstance(tau_filter, (bool, np.bool_)):
    raise ValueError("tau_filter cannot be a boolean.")
try:
    tau_filter_float = float(tau_filter)
except (TypeError, ValueError):
    raise ValueError("tau_filter must be numeric.")
if not np.isfinite(tau_filter_float):
    raise ValueError("tau_filter must be finite.")
if tau_filter_float < 0:
    raise ValueError("tau_filter must be nonnegative.")
# Compute total log probabilities per candidate by summing over horizon
total_with_result = np.sum(logp_with_result, axis=1)
total_call_only = np.sum(logp_call_only, axis=1)
total_no_call = np.sum(logp_no_call, axis=1)
# Compute margin = log p(with result) - max(log p(call only), log p(no call))
margins = total_with_result - np.maximum(total_call_only, total_no_call)
# Keep mask where margin > tau_filter
keep_mask = margins > tau_filter_float
return keep_mask, margins
